import { defineRouteMiddleware, type StarlightRouteData } from "@astrojs/starlight/route-data";

type SidebarEntry = StarlightRouteData["sidebar"][number];

/**
 * Display labels for autogenerated sidebar subgroups, keyed by directory name.
 * Starlight labels these with the raw directory name and has no config option to change it.
 */
const subgroupLabels: Record<string, string> = {
    hooks: "Hooks",
    components: "Components",
    css: "CSS",
    principle: "Principles",
    std: "Standard Library",
    "design-patterns": "Design Patterns",
};

function relabelSubgroups(entries: SidebarEntry[], nested = false) {
    for (const entry of entries) {
        if (entry.type !== "group") continue;
        if (nested) entry.label = subgroupLabels[entry.label] ?? entry.label;
        relabelSubgroups(entry.entries, true);
    }
}

export const onRequest = defineRouteMiddleware((context) => {
    relabelSubgroups(context.locals.starlightRoute.sidebar);
});
